// ─── File: AuthzDemo.java ───
package com.bank.authz;

import java.util.*;
import java.util.logging.*;

public class AuthzDemo {
    private static final Logger log = Logger.getLogger("Authz");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        Authenticator auth = new Authenticator();
        boolean who = auth.authenticate("back-office-svc", "valid-sts-token");
        log.info(() -> "Authentication (who are you?) succeeded: " + who);

        List<Statement> policy = List.of(
            new Statement("Allow", "s3:*",           "arn:aws:s3:::nbi-statements/*"),
            new Statement("Deny",  "s3:DeleteObject", "arn:aws:s3:::nbi-statements/*")
        );
        PolicyEngine engine = new PolicyEngine();

        log.info(() -> "Can PutObject?  " + engine.evaluate(policy, "s3:PutObject",    "arn:aws:s3:::nbi-statements/stmt1.pdf"));
        log.info(() -> "Can GetObject?  " + engine.evaluate(policy, "s3:GetObject",    "arn:aws:s3:::nbi-statements/stmt1.pdf"));
        log.warning(() -> "Can DeleteObject? " + engine.evaluate(policy, "s3:DeleteObject", "arn:aws:s3:::nbi-statements/stmt1.pdf"));
        log.warning(() -> "Can access other bucket? " + engine.evaluate(policy, "s3:GetObject", "arn:aws:s3:::other-bucket/x"));
    }
}

// ─── Would be in Statement.java ───
class Statement {
    final String effect, action, resource;
    Statement(String effect, String action, String resource) {
        this.effect = effect; this.action = action; this.resource = resource;
    }
    boolean matches(String act, String res) {
        boolean actMatch = action.equals(act) || action.endsWith(":*")
                && act.startsWith(action.substring(0, action.length() - 1));
        boolean resMatch = res.matches(resource.replace("*", ".*"));
        return actMatch && resMatch;
    }
}

// ─── Would be in PolicyEngine.java ───
class PolicyEngine {
    // Implements: explicit deny > explicit allow > implicit deny.
    String evaluate(List<Statement> statements, String action, String resource) {
        boolean allow = false;
        for (Statement s : statements) {
            if (s.matches(action, resource)) {
                if ("Deny".equals(s.effect)) return "DENY (explicit deny wins)";
                if ("Allow".equals(s.effect)) allow = true;
            }
        }
        return allow ? "ALLOW" : "DENY (implicit — nothing matched)";
    }
}

// ─── Would be in Authenticator.java ───
class Authenticator {
    // Authentication happens BEFORE authorization.
    boolean authenticate(String principal, String token) {
        return token != null && token.startsWith("valid-");
    }
}

// ─── Would be in BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n", r.getMillis(), r.getLevel(), r.getMessage());
    }
}
